import numpy as np

def problem(x: np.ndarray) -> float:
    a, b, c, d = x
    return (
        0.1 * a**4 + 0.2 * b**3 - 0.15 * c**2 + 0.05 * d + 0.1 * a * b - 0.05 * b * c +
        0.2 * a * c + 0.1 * np.sin(a) + 0.05 * np.cos(b) + 0.001*np.exp(0.1*a + 0.2*b - 0.3*c + 0.4*d)
    )

import numpy as np

def problem(x: np.ndarray) -> float:
    a, b, c, d = x
    return (
        0.2 * a**2 + 0.3 * b**2 + 0.1 * c**3 + 0.1 * a * b +
        0.2 * np.sin(a) + 0.1 * np.cos(b) + 0.01 * (a - b + c - d)**2
    )

import numpy as np

def problem(x: np.ndarray) -> float:
    a, b, c, d = x
    return (
        0.5 * (a**2 + b**2 + c**2 + d**2) +  0.1 * a * b -0.3*(a**3) + 0.2 * np.sin(3*a) +  0.01 * (a*b*c*d)
    )
